/**
 * Real Madani mushaf (QPC V2, 1421H) — word-level layout data.
 *
 * Data: public/quran-mushaf-v2.json (same file, moved out of the
 * webpack bundle by the hifz-completion performance work so the
 * browser can preload it from the page head), generated by
 * scripts/generate-quran-mushaf-v2.py from the licensed QPC V2 15-line
 * layout (QUL issue #596: layouts free to bundle/transform) plus
 * Tanzil Uthmani v1.1 (CC BY 3.0). The file stores WHERE each Tanzil
 * word sits in the print — per line, runs of (surah, ayah,
 * Tanzil-token-index, count, first-QUL-id) — not the word text
 * itself (see docs/quran/hifz-redesign-phase3-notes.md for the full
 * licence substitution rationale and the word-id mapping derivation).
 *
 * Phase-1 hifz fix (2026-11-07): the word text source is now the
 * real QPC V2 glyph script when available — expandV2Page takes an
 * optional QUL-id → glyph-string map (one per-page JSON file under
 * public/quran-mushaf-v2-glyphs/, written by
 * scripts/split-quran-mushaf-v2-glyphs.py) and V2Word.text becomes
 * that glyph string (1–3 PUA chars, page-relative codes from
 * U+FC41). When the glyph map is missing or incomplete for the
 * page, the expansion falls back to Tanzil tokens for the whole
 * page (V2Expansion.glyph === false) — an honest fallback, never a
 * silent per-word substitution. The Basmalah line ('b') carries no
 * layout segments, so it still renders the Tanzil Basmalah text;
 * the ayah-end rosette stays the painted V2Rosette until visual
 * rendering proves the ayah number sits inside the marker glyph.
 * The glyph script + layout data are licence-UNCLEAR (recorded in
 * THIRD_PARTY_NOTICES.md, not claimed as licensed).
 *
 * The JSON is fetched (not dynamically imported) so the hifz study
 * page can <link rel="preload" as="fetch"> it from the server-rendered
 * head: on slow 3G the data wave used to start only after hydration
 * (~14.5s in), and the V2 chunk ending gated the mushaf (~27s). The
 * preload starts the download with the first wave instead. Callers
 * still see the same promise-cached loader, and a failed fetch
 * returns null so callers fall back to the old exact-line rendering
 * — never a blank page. The file is served with a 1-day cache +
 * stale-while-revalidate (next.config headers): if the data ever
 * changes, bump QURAN_MUSHAF_V2_URL (or the cache headers) — the URL
 * must be versioned on a data change, because repeat visitors may
 * otherwise hold the old copy for up to a day.
 *
 * Server-side note: the loader is only ever called from client
 * effects (study page, reader page view, boundaries loader). A
 * relative fetch has no origin on the server, so a server-side call
 * would fail closed to null and take the fallback path — by design.
 *
 * Word identity: every word carries BOTH keys — the app's own
 * "surah:ayah:tanzil-token-index" (the key the hifz study page,
 * the ASR mapping and the wall already use) and the layout's QUL id
 * (the print position). The one place they are not 1:1 is 37:130:
 * QUL writes "إِلْ يَاسِينَ" as one layout word, so both Tanzil
 * tokens share one QUL id (MERGED_SECOND_WORD below). The renderer
 * keys words by "s:a:w", so no collision occurs.
 */

export interface V2Segment {
  /** Surah number. */
  s: number;
  /** Ayah number. */
  a: number;
  /** 0-based Tanzil token index of the segment's first word. */
  w: number;
  /** Number of real words in this run (pause signs excluded). */
  n: number;
  /** QUL id of the segment's first word. */
  q: number;
  /** 1 when the segment's last word ends its ayah (rosette follows). */
  e: 0 | 1;
}

export type V2Line =
  | { t: 'h'; s: number; x: string }
  | { t: 'b' }
  | {
      t: 'x';
      /** First QUL id on the line (words + ayah-number tokens). */
      f: number;
      /** Last QUL id on the line. */
      l: number;
      /** 1 when the line is centered in the print. */
      c?: 1;
      seg: V2Segment[];
      /** "NUM:s:a" when the line STARTS with an ayah-end number
          token (the ayah's last word ended the previous line — the
          rosette prints at this line's start). */
      lead?: string;
    };

export interface V2Page {
  n: number;
  /** Juz of the page's last ayah (same rule as the reader's pageMeta). */
  juz: number | null;
  /** Hizb of the page's last ayah. */
  hizb: number | null;
  lines: V2Line[];
}

export interface V2MushafData {
  version: number;
  source: string;
  pages: V2Page[];
  /** "surah:ayah" carrying a rub el hizb ornament (199). */
  rubAyahs: string[];
  /** "surah:ayah:token-index" of the 15 printed sajda words. */
  sajdaWords: string[];
}

/** The one genuine 2->1 merge: both Tanzil tokens of 37:130 at
    indices 2 and 3 ("إِلْ", "يَاسِينَ") share a single QUL id. The
    second token's key — it reuses the previous word's QUL id. */
export const MERGED_SECOND_WORD = '37:130:3';

/** Standalone pause-sign tokens in Tanzil: ornaments, never words. */
export const MUSHAF_PAUSE_SIGNS = new Set(['ۚ', 'ۖ', 'ۗ', 'ۙ', 'ۘ', 'ۛ', 'ۜ']);
export const MUSHAF_SAJDA_MARK = '۩';

/** "surah:ayah:word" key of one expanded word. */
export function v2WordKey(surah: number, ayah: number, index: number): string {
  return `${surah}:${ayah}:${index}`;
}

/** Public URL of the V2 layout data (same-origin static file). The
    hifz study page preloads exactly this URL from the server-rendered
    head — keep the preload href and this constant identical, or the
    browser downloads the data twice (preload + fetch). */
export const QURAN_MUSHAF_V2_URL = '/quran-mushaf-v2.json';

/** Per-page glyph data: QUL id → glyph string (1–3 PUA chars).
    One JSON file per page, written by
    apps/web/scripts/split-quran-mushaf-v2-glyphs.py from the
    word-level QPC V2 glyph script (83,668 entries). A page's file
    holds ONLY that page's word ids — glyph codes are PAGE-RELATIVE
    (the same code is a different glyph on another page), so a glyph
    string must only ever render in its own page's QCF2NNN family. */
export type V2PageGlyphs = ReadonlyMap<number, string>;

/** Public URL of one page's glyph file (same-origin static file). */
export function v2PageGlyphsUrl(page: number): string {
  return `/quran-mushaf-v2-glyphs/p${page}.json`;
}

const glyphPromises = new Map<number, Promise<V2PageGlyphs | null>>();

/** One page's QUL-id → glyph-string map, or null when the file is
    missing or unreadable (the caller then renders Tanzil text — the
    honest fallback, never a silent substitution). Promise-cached
    per page. */
export function loadV2PageGlyphs(page: number): Promise<V2PageGlyphs | null> {
  const existing = glyphPromises.get(page);
  if (existing) return existing;
  const promise = fetch(v2PageGlyphsUrl(page))
    .then((res) => {
      if (!res.ok) return null;
      return res.json() as Promise<Record<string, string>>;
    })
    .then((obj) => {
      if (!obj) return null;
      const map = new Map<number, string>();
      for (const [k, v] of Object.entries(obj)) map.set(Number(k), v);
      return map as V2PageGlyphs;
    })
    .catch(() => null);
  glyphPromises.set(page, promise);
  return promise;
}

let dataPromise: Promise<V2MushafData | null> | null = null;

/** All 604 V2 pages (plus rub/sajda lists), or null on failure.
    Fetched once (promise-cached) from the public static file, so the
    page head can preload it; gzipped on the wire by the Next server
    (~193KB, same as the old webpack chunk). */
export function loadMushafV2(): Promise<V2MushafData | null> {
  if (!dataPromise) {
    dataPromise = fetch(QURAN_MUSHAF_V2_URL)
      .then((res) => {
        if (!res.ok) return null;
        return res.json() as Promise<V2MushafData>;
      })
      .catch(() => null);
  }
  return dataPromise;
}

/** One V2 page (1-based), or null when the data failed / is out of range. */
export async function loadV2Page(page: number): Promise<V2Page | null> {
  const data = await loadMushafV2();
  if (!data || page < 1 || page > data.pages.length) return null;
  return data.pages[page - 1];
}

/** A slice of V2 pages, inclusive, in order (empty when unavailable). */
export async function loadV2Pages(from: number, to: number): Promise<V2Page[]> {
  const data = await loadMushafV2();
  if (!data) return [];
  const out: V2Page[] = [];
  for (let p = Math.max(1, from); p <= Math.min(to, data.pages.length); p += 1) {
    out.push(data.pages[p - 1]);
  }
  return out;
}

/** First page (0-based) whose segments cover the given ayah, else null. */
export function v2PageIndexFor(
  pages: V2Page[],
  surah: number,
  ayah: number,
): number | null {
  for (let p = 0; p < pages.length; p += 1) {
    for (const line of pages[p].lines) {
      if (line.t !== 'x') continue;
      for (const seg of line.seg) {
        if (seg.s === surah && seg.a === ayah) return p;
      }
    }
  }
  return null;
}

/** First ayah on the page (first text segment), or null for an empty page. */
export function v2FirstAyahOfPage(page: V2Page): { surah: number; ayah: number } | null {
  for (const line of page.lines) {
    if (line.t !== 'x' || line.seg.length === 0) continue;
    return { surah: line.seg[0].s, ayah: line.seg[0].a };
  }
  return null;
}

/** First ayah of one surah on a page, or null when the surah is not
    on the page (page navigation: the previous/next page may belong
    entirely to another surah, and then the button does nothing). */
export function v2FirstAyahOfSurahOnPage(page: V2Page, surah: number): number | null {
  for (const line of page.lines) {
    if (line.t !== 'x') continue;
    for (const seg of line.seg) {
      if (seg.s === surah) return seg.a;
    }
  }
  return null;
}

/** Unique "surah:ayah" refs on the page, in order (for fetching texts). */
export function v2PageAyahs(page: V2Page): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  for (const line of page.lines) {
    if (line.t !== 'x') continue;
    for (const seg of line.seg) {
      const key = `${seg.s}:${seg.a}`;
      if (!seen.has(key)) {
        seen.add(key);
        out.push(key);
      }
    }
  }
  return out;
}

// ------------------------------------------------------------ expansion

/** One word on a rendered V2 line, with both identities. */
export interface V2Word {
  /** "surah:ayah:tanzil-token-index" — the app's word key. */
  key: string;
  surah: number;
  ayah: number;
  /** Tanzil whitespace-token index inside the ayah. */
  index: number;
  /** QUL layout word id (shared by the 37:130 pair). */
  qulId: number;
  /** Word text: the glyph string (1–3 PUA chars) when the
      expansion ran in glyph mode (V2Expansion.glyph === true),
      else the verbatim Tanzil token text. In glyph mode the merged
      second word of 37:130 carries '' — its glyph was already
      emitted by the first word sharing its QUL id. */
  text: string;
  /** Standalone pause sign printed attached after this word, if any. */
  pauseAfter?: string;
  /** A rub el hizb ornament (۞) prints before this word. */
  rubBefore: boolean;
  /** A sajda mark (۩) prints after this word. */
  sajdaAfter: boolean;
  /** The ayah ends here (rosette with the ayah number follows). */
  endsAyah: boolean;
}

export type V2RenderLine =
  | { kind: 'header'; surah: number; name: string }
  | { kind: 'basmala' }
  | {
      kind: 'text';
      centered: boolean;
      /** Ayah number of a leading rosette, or null. */
      leadAyah: number | null;
      words: V2Word[];
    };

export interface V2Expansion {
  lines: V2RenderLine[];
  /** False when any ayah's tokens are missing or do not match the
      layout segments — the caller must fall back to the old
      exact-line rendering instead of showing a wrong page. */
  ok: boolean;
  problems: string[];
  /** True when every word's text came from the glyph map (render in
      the page's QCF2NNN family, solid black, no tajweed colours on
      PUA text). False when the glyph map was missing or incomplete
      for this page and the words fell back to Tanzil tokens. */
  glyph: boolean;
}

/**
 * Expand one V2 page into renderable lines.
 *
 * `tokens` maps "surah:ayah" to the ayah's verbatim Tanzil tokens
 * (whitespace split, Basmalah prefix and pause signs included).
 * The expansion is STRICT: it verifies, for every ayah on the page,
 * that the layout segments cover exactly the ayah's real words
 * (non-ornament tokens, minus a leading Basmalah prefix when the
 * segments start at token index 4). Any mismatch returns ok:false
 * with the problem listed — never a silently wrong page.
 *
 * `glyphs` (optional) maps QUL id → glyph string for this page.
 * When it is present AND holds every QUL id the page's segments use,
 * the word text comes from the glyph map (V2Expansion.glyph ===
 * true) — one id, one glyph string, so the 37:130 merge resolves
 * itself: both Tanzil tokens share one QUL id whose glyph string
 * already holds "إِلْ يَاسِينَ" as one printed unit, and the second
 * word's text is '' (its glyph was already emitted). When the map
 * is absent or incomplete for the page, the words fall back to the
 * Tanzil tokens for the WHOLE page (glyph === false) — never a
 * per-word mix of glyph and Tanzil text.
 */
export function expandV2Page(
  data: V2MushafData,
  page: V2Page,
  tokens: ReadonlyMap<string, readonly string[]>,
  glyphs?: ReadonlyMap<number, string> | null,
): V2Expansion {
  const problems: string[] = [];
  const rub = new Set(data.rubAyahs);
  const sajda = new Set(data.sajdaWords);
  const lines: V2RenderLine[] = [];

  // Strict per-ayah coverage check, before building any word.
  for (const ref of v2PageAyahs(page)) {
    const [s, a] = ref.split(':').map(Number);
    const toks = tokens.get(ref);
    if (!toks) {
      problems.push(`missing tokens for ${ref}`);
      continue;
    }
    const covered = new Set<number>();
    for (const line of page.lines) {
      if (line.t !== 'x') continue;
      for (const seg of line.seg) {
        if (seg.s !== s || seg.a !== a) continue;
        for (let j = 0; j < seg.n; j += 1) covered.add(seg.w + j);
      }
    }
    const firstCovered = covered.size > 0 ? Math.min(...covered) : -1;
    if (firstCovered !== 0 && firstCovered !== 4) {
      problems.push(`${ref}: first covered token ${firstCovered}, expected 0 or 4`);
      continue;
    }
    const expected = new Set<number>();
    for (let i = firstCovered; i < toks.length; i += 1) {
      const tok = toks[i];
      if (MUSHAF_PAUSE_SIGNS.has(tok) || tok === MUSHAF_SAJDA_MARK) continue;
      expected.add(i);
    }
    if (covered.size !== expected.size || ![...covered].every((i) => expected.has(i))) {
      problems.push(
        `${ref}: layout covers ${covered.size} words, tokens have ${expected.size}`,
      );
    }
  }

  // Words are built with empty text first: the text source (glyph
  // map vs Tanzil tokens) is decided only after every QUL id the
  // page uses is known, so the choice is per page, never per word.
  const allWords: V2Word[] = [];
  const usedQulIds = new Set<number>();

  for (const line of page.lines) {
    if (line.t === 'h') {
      lines.push({ kind: 'header', surah: line.s, name: line.x });
      continue;
    }
    if (line.t === 'b') {
      lines.push({ kind: 'basmala' });
      continue;
    }
    const words: V2Word[] = [];
    let leadAyah: number | null = null;
    if (line.lead) {
      const parts = line.lead.split(':');
      leadAyah = Number(parts[2]);
    }
    for (const seg of line.seg) {
      const toks = tokens.get(`${seg.s}:${seg.a}`) ?? [];
      // First real-word index of this ayah (for the rub ornament):
      // the smallest covered token index of the ayah's segments.
      let nextQ = seg.q;
      let prevQ = seg.q;
      for (let j = 0; j < seg.n; j += 1) {
        const w = seg.w + j;
        const key = v2WordKey(seg.s, seg.a, w);
        let qulId: number;
        if (key === MERGED_SECOND_WORD) {
          qulId = prevQ; // shares the previous word's QUL id
        } else {
          qulId = nextQ;
          nextQ += 1;
        }
        prevQ = qulId;
        usedQulIds.add(qulId);
        const after = toks[w + 1];
        const word: V2Word = {
          key,
          surah: seg.s,
          ayah: seg.a,
          index: w,
          qulId,
          text: '',
          rubBefore:
            rub.has(`${seg.s}:${seg.a}`) &&
            w === firstRealWordIndex(page, seg.s, seg.a),
          sajdaAfter: sajda.has(key),
          endsAyah: seg.e === 1 && j === seg.n - 1,
        };
        if (after !== undefined && MUSHAF_PAUSE_SIGNS.has(after)) {
          word.pauseAfter = after;
        }
        words.push(word);
        allWords.push(word);
      }
    }
    lines.push({ kind: 'text', centered: line.c === 1, leadAyah, words });
  }

  // Glyph mode is all-or-nothing per page: the map must hold every
  // QUL id the page's segments use. Otherwise the whole page falls
  // back to Tanzil tokens (glyph === false).
  const useGlyph =
    glyphs !== undefined &&
    glyphs !== null &&
    [...usedQulIds].every((id) => glyphs.has(id));
  for (const word of allWords) {
    if (useGlyph && glyphs) {
      // One id, one glyph string. The merged second word of 37:130
      // shares its QUL id with the previous word, whose glyph string
      // already holds both halves ("إِلْ يَاسِينَ") — it renders ''.
      word.text =
        word.key === MERGED_SECOND_WORD ? '' : (glyphs.get(word.qulId) ?? '');
    } else {
      word.text = tokens.get(`${word.surah}:${word.ayah}`)?.[word.index] ?? '';
    }
  }

  return { lines, ok: problems.length === 0, problems, glyph: useGlyph };
}

/** Smallest token index the layout covers for one ayah on this page
    (its first real word — the rub ornament, if any, sits before it). */
function firstRealWordIndex(page: V2Page, surah: number, ayah: number): number {
  let first = Number.POSITIVE_INFINITY;
  for (const line of page.lines) {
    if (line.t !== 'x') continue;
    for (const seg of line.seg) {
      if (seg.s === surah && seg.a === ayah && seg.w < first) first = seg.w;
    }
  }
  return first;
}

// ------------------------------------------------- Phase 4 hook types

/**
 * Per-word display states the hifz study page (Phase 4) drives on
 * the renderer. The renderer only HONOURS them — it never computes
 * grades, and live-recording behaviour itself stays in Phase 4.
 */
export type MushafWordState =
  | 'correct'
  | 'close'
  | 'wrong'
  | 'skipped'
  | 'peek'
  | 'recent';

export interface MushafWordView {
  /** True hides the word (layout-preserving: visibility hidden). */
  hidden?: boolean;
  /** Feedback colour state, or null for plain ink. */
  state?: MushafWordState | null;
}

/** Word views keyed by "surah:ayah:word"; ayah views keyed by "surah:ayah". */
export type MushafWordViews = Record<string, MushafWordView>;
